use std::{fs,io::Write,process::{Command,Stdio}};
fn main(){let d="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-gaussian-fr-cios";let index:serde_json::Value=serde_json::from_slice(&fs::read(format!("{d}/artifact-index.json")).unwrap()).unwrap();let mut input=String::new();for(f,h)in index.as_object().unwrap(){assert!(!f.contains('\n')&&!f.contains('\\'));input.push_str(&format!("{}  artifacts/{f}\n",h.as_str().unwrap()));}let mut child=Command::new("sha256sum").args(["--check","--strict","-"]).current_dir(d).stdin(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();assert!(child.wait().unwrap().success());println!("Independent GNU sha256sum verified {} artifact hashes",index.as_object().unwrap().len());}
